def validate_call(call, tools):
    schema = tools.get(call.get('name'))
    if schema is None:
        return f"unknown tool {call.get('name')!r}"
    args = call.get('arguments', {})
    props = schema.get('properties', {})
    for name in schema.get('required', []):
        if name not in args:
            return f'missing required argument {name!r}'
    checks = {
        'string': lambda v: isinstance(v, str),
        'integer': lambda v: isinstance(v, int) and not isinstance(v, bool),
        'number': lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
        'boolean': lambda v: isinstance(v, bool),
    }
    for name, value in args.items():
        if name not in props:
            return f'unknown argument {name!r}'
        if not checks[props[name]['type']](value):
            return f"argument {name!r} should be {props[name]['type']}"
    return None

